  "implementation": "def solve(case):
    import json
    items = case.get('items')
    required = case.get('required_failure_items')
    unresolved = case.get('unresolved_without')
    if not isinstance(items, list) or not isinstance(required, list) or not isinstance(unresolved, list):
        raise ValueError('Invalid case structure')
    item_set = set(items)
    for f in required:
        if f not in item_set:
            raise ValueError(f'Required failure item {f} not in items')
    for u in unresolved:
        if u not in item_set:
            raise ValueError(f'Unresolved without item {u} not in items')
    def test_config(config):
        config_set = set(config)
        for u in unresolved:
            if u not in config_set:
                return 'UNRESOLVED'
        for f in required:
            if f not in config_set:
                return 'PASS'
        return 'FAIL'
    initial = list(items)
    if test_config(initial) != 'FAIL':
        raise ValueError('Initial configuration must produce FAIL')
    config = initial
    test_count = 1
    n = 2
    while n <= len(config):
        chunk_size = (len(config) + n - 1) // n
        subsets = [config[i:i+chunk_size] for i in range(0, len(config), chunk_size)]
        reduced = False
        for subset in subsets:
            test_count += 1
            if test_config(subset) == 'FAIL':
                config = subset
                n = 2
                reduced = True
                break
        if reduced:
            continue
        for subset in subsets:
            subset_set = set(subset)
            complement = [x for x in config if x not in subset_set]
            test_count += 1
            if test_config(complement) == 'FAIL':
                config = complement
                n = 2
                reduced = True
                break
        if reduced:
            continue
        n = min(n * 2, len(config))
    minimal_failure = config
    terminal_outcome = test_config(config)
    return {
        'minimal_failure': minimal_failure,
        'test_count': test_count,
        'terminal_outcome': terminal_outcome
    }"
}
